facts=[]
def fact(i,ids,statement,limit,needles,kind='facility'):
 idx=fidx if kind=='facility' else pidx if kind=='purchase' else ridx
 root=B/'facilities' if kind=='facility' else B/'purchase' if kind=='purchase' else B
 refs=[]
 for sid in ids:
  x=idx[sid];tf=x.get('textFile') or x.get('text_file');rf=x.get('rawFile') or x.get('file') or x.get('raw_file')
  refs.append({'id':sid,'url':x.get('finalUrl') or x.get('final_url') or x.get('url') or x.get('requestedUrl'),'textFile':str((root/tf).relative_to(B)) if tf else None,'rawFile':str((root/rf).relative_to(B)) if rf else None,'localTextSha256':sha(root/tf) if tf else None,'matchedLines':[j+1 for j,l in enumerate((root/tf).read_text().splitlines()) if any(n in l for n in needles)] if tf else [],'networkStatus':'Original capture status only; this reviewer did not issue HTTP requests'})
 facts.append({'id':i,'category':'직접 확인','finding':statement,'sources':refs,'copyBoundary':limit})
